static void send(reader::Touch& touch,unsigned short type,unsigned short code,int value,spike::Ns time,bool busy=false){input_event e{};e.type=type;e.code=code;e.value=value;CHECK(touch.feed(e,busy,time)==reader::Action::None);}
static void down(reader::Touch& t,const Range& r){send(t,EV_ABS,ABS_MT_SLOT,0,1);send(t,EV_ABS,ABS_MT_TRACKING_ID,7,1);send(t,EV_ABS,ABS_MT_POSITION_X,r.sx,1);send(t,EV_ABS,ABS_MT_POSITION_Y,r.sy,1);send(t,EV_SYN,SYN_REPORT,0,1);}
static void move(reader::Touch& t,const Range& r,bool busy=false){send(t,EV_ABS,ABS_MT_POSITION_X,r.ex,500000001,busy);send(t,EV_ABS,ABS_MT_POSITION_Y,r.ey,500000001,busy);send(t,EV_SYN,SYN_REPORT,0,500000001,busy);}
static reader::Touch::Tap up(reader::Touch& t){send(t,EV_ABS,ABS_MT_TRACKING_ID,-1,600000001);send(t,EV_SYN,SYN_REPORT,0,600000001);return t.takeTap();}
static reader::Touch::Tap gesture(ux::Shell& s,const Range& r){reader::Touch t;t.testAxes({0,1619},{0,2159});t.interactionMode(s.touchMode(),s.version());t.toolbar(s.touchToolbar());t.selectionHandles(s.selectionHandles());down(t,r);move(t,r);auto tap=up(t);if(!tap.valid||!tap.drag)std::fprintf(stderr,"GESTURE_ROUTE_INPUT mode=%u state=%u from=%d,%d to=%d,%d gesture=%u valid=%u drag=%u\n",unsigned(s.touchMode()),unsigned(s.state()),r.sx,r.sy,r.ex,r.ey,unsigned(tap.gesture),tap.valid,tap.drag);CHECK(tap.valid&&tap.drag&&!tap.longPress&&!tap.cancelled&&tap.epoch==s.version());return tap;}
static bool route(ux::Shell& s,const reader::Touch::Tap& t){return t.valid&&t.drag&&s.touchDrag(t);}
static void settle(ux::Shell& s,Canvas& c){until([&]{s.tick();c.changes();CHECK(!s.failed());return s.notesPanel()&&s.notesPanel()->view().ready&&s.notesPanel()->canLeave();});CHECK(s.notesPanel()->view().error.isEmpty());}
static void closePanel(ux::Shell& s,Canvas& c){until([&]{s.tick();c.changes();CHECK(!s.failed());auto* p=s.notesPanel();return !p->active()||(!p->view().busy&&!p->view().highlightCreated);}); /* a new highlight closes its own sheet; an existing one shows its options */if(s.notesPanel()->active())CHECK(uitest::notes(s,ib::notes::NoteDone));until([&]{s.tick();c.changes();CHECK(!s.failed());return !s.notesPanel()->active()&&!s.styledInk()->status().busy;});CHECK(s.state()==ux::State::Clean&&s.selectionEnabled());}
static void highlightTool(ux::Shell& s,Canvas& c){if(s.styledInk()->style().tool!=styled::Tool::Highlighter)CHECK(s.styledInk()->selectTool(styled::Tool::Highlighter));until([&]{s.tick();c.changes();CHECK(!s.failed());return !s.styledInk()->status().busy;});CHECK(s.selectionEnabled());}
static void anchorMatches(const QJsonObject& h,const Range& r,const library::Document& book,const QString& pageId){auto a=h["anchor"].toObject();CHECK(a["document"]==book.id&&a["revision"]==book.sha256&&a["page"]==0&&a["pageId"]==pageId);CHECK(a["start"]==r.start&&a["end"]==r.end&&a["excerpt"]==r.text&&a["quads"].toArray()==r.quads);}
